#include <string>

class Noisy
{
public:
    Noisy(std::string& log, char name) : m_log{ log }, m_name{ name } { m_log += '+'; m_log += m_name; }
    ~Noisy() { m_log += '-'; m_log += m_name; }

private:
    std::string& m_log;
    char m_name;
};

void demo(std::string& log)
{
    Noisy a{ log, 'A' };
    {
        Noisy b{ log, 'B' };
        Noisy c{ log, 'C' };
    }
    Noisy d{ log, 'D' };
}
